/** An n x m grid of panel rects (column-major so panels fill down then across). */
function grid(cols, rows, n) {
  const gap = 0.012;
  const cw = (1 - gap * (cols - 1)) / cols;
  const ch = (1 - gap * (rows - 1)) / rows;
