.brand { display: flex; align-items: center; gap: 12px; margin-bottom: 8px; }
.logo { width: 44px; height: 44px; border-radius: 10px; display: grid; place-items: center; font-family: Anton, sans-serif; font-size: 20px; color: #fff; background: linear-gradient(160deg, #ff7a3c, #ff2e88 55%, #7b2ff7); box-shadow: 0 0 18px rgba(255, 46, 136, 0.45); }
.brand h1 { margin: 0; font-family: Anton, sans-serif; font-weight: 400; font-size: 24px; letter-spacing: 0.5px; }
.tag { margin: 0; color: #9d8fc4; font-size: 12px; }

.group { margin-top: 18px; padding-top: 14px; border-top: 1px solid #241a3d; }
.group h2 { margin: 0 0 10px; font-size: 11px; letter-spacing: 1.6px; text-transform: uppercase; color: #b39ddb; font-weight: 700; }

.dropzone { border: 1.5px dashed #4a3a78; border-radius: 10px; padding: 12px; text-align: center; cursor: pointer; transition: 0.15s; }
.dropzone:hover, .dropzone.drag { border-color: #ff2e88; background: rgba(255, 46, 136, 0.08); }
.dropzone p { margin: 0; pointer-events: none; }
.dropzone strong { display: block; font-size: 14px; color: #ffd9ec; }
.dropzone span { font-size: 12px; color: #9d8fc4; }

.thumbs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 10px; }
.thumbs img { width: 100%; aspect-ratio: 1; object-fit: cover; border-radius: 6px; cursor: pointer; border: 2px solid transparent; }
.thumbs img:hover { border-color: #6a55b0; }
.thumbs img.active { border-color: #ff2e88; box-shadow: 0 0 10px rgba(255, 46, 136, 0.5); }

.chiprow { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { font: 12px/1 system-ui; padding: 7px 10px; border-radius: 999px; border: 1px solid #3a2c66; background: #1c1335; color: #cfc4ea; cursor: pointer; }
.chip:hover { border-color: #6a55b0; }
.chip.active { background: linear-gradient(120deg, #ff7a3c33, #ff2e8855); border-color: #ff2e88; color: #fff; }

.row { display: flex; align-items: center; gap: 10px; margin: 8px 0; }
.row > span { width: 88px; min-width: 88px; color: #b9aed8; font-size: 12.5px; }
.row input[type=text], .row select { flex: 1; font: inherit; font-size: 13px; padding: 6px 8px; background: #1a1230; border: 1px solid #3a2c66; border-radius: 6px; color: #eee; min-width: 0; }
.row input[type=range] { flex: 1; accent-color: #ff2e88; }
.row b { width: 34px; text-align: right; font-size: 12px; color: #9d8fc4; }

.check { display: flex; align-items: center; gap: 8px; margin: 7px 0; font-size: 13px; color: #cfc4ea; cursor: pointer; }
.check input { accent-color: #ff2e88; }
.check select { font: inherit; font-size: 12px; background: #1a1230; border: 1px solid #3a2c66; border-radius: 6px; color: #eee; }

.stars { display: flex; gap: 4px; }
.stars button { font-size: 20px; padding: 0 2px; background: none; border: 0; cursor: pointer; color: #4a3a78; filter: grayscale(1); }
.stars button.lit { color: #ffd640; filter: none; text-shadow: 0 0 8px rgba(255, 214, 64, 0.6); }

.actions .exports { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.exports button { font: 700 12.5px system-ui; padding: 10px 6px; border: 0; border-radius: 8px; cursor: pointer; color: #fff; background: linear-gradient(135deg, #ff7a3c, #ff2e88); box-shadow: 0 2px 12px rgba(255, 46, 136, 0.35); }
.exports button:hover { filter: brightness(1.12); }
#status { margin: 10px 0 0; font-size: 12px; color: #7de0a6; min-height: 16px; }

/* ---------- stage ---------- */
.stage { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 16px; min-width: 0; background: radial-gradient(1200px 800px at 50% 20%, #1a1030, #0d0916 70%); }
.toolbar { width: 100%; max-width: 720px; display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.tbgroup { display: flex; gap: 6px; }
.toolbar button { width: 36px; height: 32px; font-size: 15px; border-radius: 8px; border: 1px solid #3a2c66; background: #1c1335; color: #e8e2f2; cursor: pointer; }
.toolbar button:hover { border-color: #ff2e88; }
.toolbar button:disabled { opacity: 0.35; cursor: default; }
#hint { margin: 0; font-size: 12px; color: #9d8fc4; }
#cover { max-width: min(76vh, calc(100vw - 400px)); max-height: 82vh; width: auto; height: auto; border-radius: 6px; box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6), 0 0 0 1px #2a1f45; cursor: crosshair; background: #120a1e; }

/* ---------- shot modes (deterministic screenshots) ---------- */
body.shot-cover .side, body.shot-cover .toolbar { display: none; }
body.shot-cover .stage { padding: 0; background: #000; }
body.shot-cover #cover { max-width: 100vw; max-height: 100vh; width: 100vw; height: 100vh; object-fit: contain; border-radius: 0; box-shadow: none; }
body.shot-editor #cover { max-width: min(72vh, 55vw); }
